      for (const [key, saved] of [
        ['NODE_COMPILE_CACHE', savedCompileCache],
        ['NODE_COMPILE_CACHE_PORTABLE', savedPortable],
        ['NODE_DISABLE_COMPILE_CACHE', savedDisable],
