            if (
              typeof path === 'string' &&
              path.includes('/fake/repo/generated/.codex/config.toml')
            ) {
              return true;
            }
            if (
              typeof path === 'string' &&
              path.includes('/fake/repo/generated/.codex/agents')
            ) {
              return false; // No agent files to copy for simplicity
